import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Deduzione logica","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/k_logica/kb/kbg.md","filePath":"lezioni/k_logica/kb/kbg.md"}`),a={name:`lezioni/k_logica/kb/kbg.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="deduzione-logica" tabindex="-1">Deduzione logica <a class="header-anchor" href="#deduzione-logica" aria-label="Permalink to “Deduzione logica”">​</a></h1><p>La <strong>deduzione logica</strong> (da non confondere assolutamente con l&#39;implicazione materiale) è il ragionamento che è base della dimostrazione di ogni teorema. Non è un connettivo logico e pertanto non ha una tavola di verità.</p><hr><p>Un teorema viene sempre enunciato nel seguente modo:</p><p class="text-red">[<strong>Da Ipotesi segue Tesi</strong>]</p><p>cioè</p><p class="text-red">[<strong>Se vale l&#39;Ipotesi allora vale la Tesi</strong>]</p><p>Ma, contrariamente all&#39;implicazione materiale, stavolta abbiamo una relazione di causa nel senso che l&#39;Ipotesi (considerata sempre vera) è causa della verità della Tesi.</p><hr><p>L&#39;ipotesi è sempre vera perché non ha significato parlare di un teorema la cui ipotesi sia falsa. Inoltre gli argomenti di Ipotesi e Tesi devono essere correlati ed omogenei.</p><p class="text-red">Ad esempio è valido dire: [<strong>Se un triangolo ha due lati uguali allora ha due angoli uguali</strong>]</p><p class="text-red">mentre non ha senso dire: [<strong>Se un triangolo ha due lati uguali allora l&#39;ombrello è aperto</strong>]</p><hr><blockquote><p>In alcuni testi si usa il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\to</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">→</span></span></span></span> (una linea sola) per indicare l&#39;implicazione materiale ed il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⇒</mo></mrow><annotation encoding="application/x-tex">\\Rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">⇒</span></span></span></span> (con doppia linea) per la deduzione logica, ma in altri testi viene indicato diversamente. Tu cerca di usare gli stessi simboli che usa il tuo Insegnante.</p></blockquote>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};